package com.sphere.core.clhep.geometry;

import com.sphere.core.clhep.vector.Hep3Vector;

/**
 * CLHEP's HepGeom::Point3D&lt;double&gt; (Geometry/Point3D.h, Point3D.cc): a point, which a transformation moves
 * by its rotation and its translation. Generated by gen_geometry.py.
 */
public class Point3D extends BasicVector3D {

    public Point3D() {
        super();
    }

    public Point3D(double x1, double y1, double z1) {
        super(x1, y1, z1);
    }

    /** From the first three of an array. */
    public Point3D(float[] a) {
        super(a[0], a[1], a[2]);
    }

    public Point3D(double[] a) {
        super(a[0], a[1], a[2]);
    }

    public Point3D(BasicVector3DF v) {
        super(v);
    }

    public Point3D(Hep3Vector v) {
        super(v.x(), v.y(), v.z());
    }

    public Point3D(BasicVector3D v) {
        super(v);
    }

    public double distance2() {
        return mag2();
    }

    public double distance2(Point3D p) {
        final double dx = p.x() - x();
        final double dy = p.y() - y();
        final double dz = p.z() - z();
        return dx * dx + dy * dy + dz * dz;
    }

    public double distance() {
        return Math.sqrt(distance2());
    }

    public double distance(Point3D p) {
        return Math.sqrt(distance2(p));
    }

    /** This point moved by m. */
    public Point3D transform(Transform3D m) {
        final double vx = x();
        final double vy = y();
        final double vz = z();
        set((m.xx() * vx + m.xy() * vy + m.xz() * vz + m.dx()),
            (m.yx() * vx + m.yy() * vy + m.yz() * vz + m.dy()),
            (m.zx() * vx + m.zy() * vy + m.zz() * vz + m.dz()));
        return this;
    }
}
